import json
import re
import unicodedata
from html import unescape
from pathlib import Path


TASK_DIR = Path(__file__).resolve().parent
REPO_ROOT = TASK_DIR.parents[2]
PACKAGE_DIR = REPO_ROOT / "event_packages" / "standard_event_packages" / "packages" / "CSX-312"
OUT_PATH = TASK_DIR / "computed_gt.json"
TARGET_FAMILY = "candidate_explanation_score_ledger"

SOURCE_FILES = [
    "metadata/event.json",
    "data/event_reports/event_reports_003_Locked_event_anchor_2018_Kilauea_eruption.json",
    "data/event_reports/event_reports_004_USGS_Kilauea_2018_summit_collapse_and_Lower_East_Rift_Zone_eruption.html",
    "data/event_catalogs/event_catalogs_004_04_event_specific_disaster_catalog_GDACS_event_list_for_package_time_window.json.json",
    "data/physical_hazard/physical_hazard_004_GPM_IMERG_V07_event_accumulated_precipitation.json",
]

RUBRIC_CRITERIA = [
    {
        "name": "Answer shape",
        "points": 3,
        "description": "Returns compact JSON with target_family, metrics, flags, scores, answer, and one computed_consequence.",
        "partial_credit": "Give partial credit when the final label is present but one ledger block is incomplete.",
    },
    {
        "name": "Metric extraction",
        "points": 4,
        "description": "Extracts fissure length 6.8 km, lava area 35.5 sq km, minimum lava rate 100 m3/s, Mw 6.9 earthquake, summit-collapse Mw 4.7-5.4, and precipitation maximum 193.836 mm within tolerance.",
        "partial_credit": "Give partial credit for at least four correct metrics with units or recognizable field names.",
    },
    {
        "name": "Integrated-score formula",
        "points": 4,
        "description": "Applies the integrated score formula exactly: 2*orange_alert + 2*200yr_scale + 2*lava_extent + 1*effusion + 1*quake + 1*collapse_energy + 1*summit_sequence.",
        "partial_credit": "Give partial credit for using the right gates but making one weight or arithmetic error.",
    },
    {
        "name": "Counter-score tests",
        "points": 3,
        "description": "Computes the counter scores as rainfall_context = 2, ash_only = 0, and earthquake_only = 0 using the defined tests.",
        "partial_credit": "Give partial credit for rejecting the counterlabels qualitatively while omitting one score.",
    },
    {
        "name": "Decision rule and label",
        "points": 3,
        "description": "Uses integrated_score >= 8 and integrated_score > max(counter_scores) to return integrated_lerz_lava_collapse_chain.",
        "partial_credit": "Give partial credit when the label is correct but the threshold comparison is not shown.",
    },
    {
        "name": "Computed consequence",
        "points": 2,
        "description": "States only the short consequence supported by the ledger: rainfall remains contextual while the coupled LERZ lava, summit-collapse, and earthquake chain dominates.",
        "partial_credit": "Give partial credit for a concise event-specific consequence with one minor unsupported embellishment.",
    },
    {
        "name": "No overclaim",
        "points": 1,
        "description": "Avoids unsupported response advice, casualty/loss totals, road-closure claims, gas concentrations, ashfall depths, or treating the task as a broad disaster interpretation.",
        "partial_credit": "No credit for this item if the answer centers operational advice or uncomputed impacts.",
    },
]


def read_json(relative_path):
    with (PACKAGE_DIR / relative_path).open("r", encoding="utf-8") as handle:
        return json.load(handle)


def read_text(relative_path):
    return (PACKAGE_DIR / relative_path).read_text(encoding="utf-8", errors="replace")


def ascii_text(value):
    normalized = unicodedata.normalize("NFKD", str(value))
    return normalized.encode("ascii", "ignore").decode("ascii")


def strip_html(value):
    text = re.sub(r"<script\b.*?</script>", " ", value, flags=re.I | re.S)
    text = re.sub(r"<style\b.*?</style>", " ", text, flags=re.I | re.S)
    text = re.sub(r"<[^>]+>", " ", text)
    text = ascii_text(unescape(text))
    return re.sub(r"\s+", " ", text).strip()


def first_float(pattern, text, flags=re.I):
    match = re.search(pattern, text, flags)
    if not match:
        raise ValueError(f"Pattern not found: {pattern}")
    return float(match.group(1))


def stat(relative_path, key):
    return read_json(relative_path)["stats"][key]


def find_kilauea_gdacs_feature(catalog):
    for feature in catalog.get("features", []):
        props = feature.get("properties", {})
        if props.get("eventtype") == "VO" and "kilauea" in str(props.get("eventname", "")).lower():
            return props
    raise ValueError("Kilauea GDACS volcano feature not found")


def round_float(value, digits=3):
    return round(float(value), digits)


def build_result():
    event = read_json("metadata/event.json")
    anchor = read_json("data/event_reports/event_reports_003_Locked_event_anchor_2018_Kilauea_eruption.json")
    gdacs = read_json("data/event_catalogs/event_catalogs_004_04_event_specific_disaster_catalog_GDACS_event_list_for_package_time_window.json.json")
    report_text = strip_html(
        read_text("data/event_reports/event_reports_004_USGS_Kilauea_2018_summit_collapse_and_Lower_East_Rift_Zone_eruption.html")
    )
    lower_text = report_text.lower()

    gdacs_props = find_kilauea_gdacs_feature(gdacs)
    gdacs_alert_level = gdacs_props["alertlevel"].title()
    gdacs_alert_score = float(gdacs_props["alertscore"])

    fissure_length_km = first_float(r"fissures opened in the LERZ .*?extending ~(\d+(?:\.\d+)?) kilometers", report_text)
    main_earthquake_mw = first_float(r"moment magnitude \(Mw\) (\d+(?:\.\d+)?)", report_text)
    minimum_lava_rate_m3_s = first_float(r"rates exceeding (\d+(?:\.\d+)?) cubic meters", report_text)
    lava_area_sq_km = first_float(r"covering (\d+(?:\.\d+)?) square kilometers", report_text)
    summit_collapse_mw_min = first_float(r"equivalent to Mw (\d+(?:\.\d+)?) to", report_text)
    summit_collapse_mw_max = first_float(r"equivalent to Mw \d+(?:\.\d+)? to (\d+(?:\.\d+)?)", report_text)
    gpm_precip_mm_max = float(
        stat("data/physical_hazard/physical_hazard_004_GPM_IMERG_V07_event_accumulated_precipitation.json", "gpm_event_precip_mm_max")
    )

    flags = {
        "orange_alert": gdacs_alert_level.lower() == "orange",
        "scale_200yr": "largest lower east rift zone" in lower_text and "caldera collapse in at least 200 years" in lower_text,
        "lava_extent": fissure_length_km >= 5 and lava_area_sq_km >= 30,
        "effusion": minimum_lava_rate_m3_s >= 100,
        "quake": main_earthquake_mw >= 6.5,
        "collapse_energy": summit_collapse_mw_min >= 4.5 and summit_collapse_mw_max >= 5.0,
        "summit_sequence": "minor explosions" in lower_text and "near-daily collapses" in lower_text,
    }
    text_flags = {
        "eruptive_fissures_opened": "eruptive fissures opened" in lower_text,
        "lava_flow_covered_area": "eventually covering 35.5 square kilometers" in lower_text,
    }

    scores = {
        "integrated": (
            (2 if flags["orange_alert"] else 0)
            + (2 if flags["scale_200yr"] else 0)
            + (2 if flags["lava_extent"] else 0)
            + (1 if flags["effusion"] else 0)
            + (1 if flags["quake"] else 0)
            + (1 if flags["collapse_energy"] else 0)
            + (1 if flags["summit_sequence"] else 0)
        ),
        "rainfall_context": 2 if gpm_precip_mm_max >= 150 else 0,
        "ash_only": 1 if gdacs_alert_level.lower() in {"green", "orange"} and not text_flags["lava_flow_covered_area"] else 0,
        "earthquake_only": 2 if main_earthquake_mw >= 6.5 and not text_flags["eruptive_fissures_opened"] else 0,
    }

    answer = (
        "integrated_lerz_lava_collapse_chain"
        if scores["integrated"] >= 8 and scores["integrated"] > max(scores["rainfall_context"], scores["ash_only"], scores["earthquake_only"])
        else "not_integrated_lerz_lava_collapse_chain"
    )

    metrics = {
        "fissure_km": round_float(fissure_length_km, 1),
        "lava_km2": round_float(lava_area_sq_km, 1),
        "rate_m3s": round_float(minimum_lava_rate_m3_s, 0),
        "eq_mw": round_float(main_earthquake_mw, 1),
        "collapse_mw": [round_float(summit_collapse_mw_min, 1), round_float(summit_collapse_mw_max, 1)],
        "precip_mm": round_float(gpm_precip_mm_max, 3),
    }
    tolerances = {
        "fissure_km": 0.2,
        "lava_km2": 0.5,
        "rate_m3s": 1,
        "eq_mw": 0.1,
        "collapse_mw": 0.1,
        "precip_mm": 0.01,
    }

    if sum(item["points"] for item in RUBRIC_CRITERIA) != 20:
        raise RuntimeError("Rubric points must sum to 20")

    primary_gt = {
        "answer": answer,
        "target_family": TARGET_FAMILY,
        "metrics": metrics,
        "flags": flags,
        "scores": scores,
        "decision_rule": "integrated>=8 and integrated>max(counters)",
        "tolerances": tolerances,
    }

    return {
        "schema_version": "1.0",
        "task_id": "CSX-312_Q1",
        "event_id": event["package_id"],
        "task_type": "numeric",
        "target_family": TARGET_FAMILY,
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "primary_gt": primary_gt,
        "event": {
            "event_id": event["package_id"],
            "event_name": ascii_text(event["event_name"]),
            "hazard_family": event["hazard_family"],
            "event_date_or_window": anchor["temporal_window"],
        },
        "key_values": {
            "gdacs_alert_level": gdacs_alert_level,
            "gdacs_alert_score": round_float(gdacs_alert_score, 1),
            "metrics": metrics,
            "flags": flags,
            "score_formula": "2*orange_alert + 2*scale_200yr + 2*lava_extent + 1*effusion + 1*quake + 1*collapse_energy + 1*summit_sequence",
            "counter_score_rules": {
                "rainfall_context": "2 if precip_mm >= 150 else 0",
                "ash_only": "1 if volcano alert is Green/Orange and lava_flow_covered_area is false else 0",
                "earthquake_only": "2 if eq_mw >= 6.5 and eruptive_fissures_opened is false else 0",
            },
            "decision_rule": "integrated>=8 and integrated>max(counters)",
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
        },
        "rubric": {
            "total_points": 20,
            "criteria": RUBRIC_CRITERIA,
        },
    }


def main():
    result = build_result()
    OUT_PATH.write_text(json.dumps(result, indent=2, ensure_ascii=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
